// ================= Index lookup =================
// Direction indices (use for both primary and secondary). ARROW_NONE as secondary = primary arrow only.
enum ArrowDir : uint8_t {
	ARROW_UP = 0,
	ARROW_DOWN = 1,
	ARROW_LEFT = 2,
	ARROW_RIGHT = 3,
	ARROW_UPLEFT = 4,
	ARROW_UPRIGHT = 5,
	ARROW_DOWNLEFT = 6,
	ARROW_DOWNRIGHT = 7,
	ARROW_NONE = 8
};

// arrowBitmaps[primary][secondary] -> 128x64 bitmap.
// If secondary == primary (not a valid combo) the primary-only bitmap is used.
static const unsigned char* const arrowBitmaps[8][9] = {
	/* up        */ { up, up_down, up_left, up_right, up_upleft, up_upright, up_downleft, up_downright, up },
	/* down      */ { down_up, down, down_left, down_right, down_upleft, down_upright, down_downleft, down_downright, down },
	/* left      */ { left_up, left_down, left, left_right, left_upleft, left_upright, left_downleft, left_downright, left },
	/* right     */ { right_up, right_down, right_left, right, right_upleft, right_upright, right_downleft, right_downright, right },
	/* upleft    */ { upleft_up, upleft_down, upleft_left, upleft_right, upleft, upleft_upright, upleft_downleft, upleft_downright, upleft },
	/* upright   */ { upright_up, upright_down, upright_left, upright_right, upright_upleft, upright, upright_downleft, upright_downright, upright },
	/* downleft  */ { downleft_up, downleft_down, downleft_left, downleft_right, downleft_upleft, downleft_upright, downleft, downleft_downright, downleft },
	/* downright */ { downright_up, downright_down, downright_left, downright_right, downright_upleft, downright_upright, downright_downleft, downright, downright },
};

#define ARROW_BITMAP(primary, secondary) (arrowBitmaps[(primary)][(secondary)])
// Example: display.drawBitmap(0, 0, ARROW_BITMAP(ARROW_UPRIGHT, ARROW_DOWN), 128, 64, WHITE);
//          display.drawBitmap(0, 0, ARROW_BITMAP(ARROW_LEFT, ARROW_NONE), 128, 64, WHITE);
